import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

// 조회 기간: 고정 SQL 조각만 사용한다 (값은 :baseDate 파라미터로 전달)
const VIEW_RANGE: Record<string, { from: string; to: string }> = {
  '일간': {
    from: "CAST(CAST(:baseDate AS date) AS timestamptz)",
    to: "CAST(CAST(:baseDate AS date) + interval '1 day' AS timestamptz)",
  },
  '주간': {
    from: "CAST(date_trunc('week', CAST(:baseDate AS date)) AS timestamptz)",
    to: "CAST(date_trunc('week', CAST(:baseDate AS date)) + interval '7 days' AS timestamptz)",
  },
  '월간': {
    from: "CAST(date_trunc('month', CAST(:baseDate AS date)) AS timestamptz)",
    to: "CAST(date_trunc('month', CAST(:baseDate AS date)) + interval '1 month' AS timestamptz)",
  },
};

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function optionalId(value: unknown, label: string): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  const text = String(value);
  if (!/^\d+$/.test(text)) {
    throw invalid(label + ' 값이 올바르지 않습니다.');
  }
  return text;
}

function pagingOf(query: Record<string, unknown>): { page: number; size: number } {
  const rawPage = query['page'];
  const rawSize = query['size'];
  let page = 0;
  let size = DEFAULT_SIZE;
  if (rawPage !== undefined && rawPage !== null && rawPage !== '') {
    if (!/^\d+$/.test(String(rawPage))) {
      throw invalid('page 값이 올바르지 않습니다.');
    }
    page = Number(rawPage);
  }
  if (rawSize !== undefined && rawSize !== null && rawSize !== '') {
    if (!/^\d+$/.test(String(rawSize)) || Number(rawSize) < 1) {
      throw invalid('size 값이 올바르지 않습니다.');
    }
    size = Math.min(Number(rawSize), MAX_SIZE);
  }
  return { page, size };
}

@Controller('api/v1')
export class FnSfr03301Controller {
  @Get('/resources')
  async listResources(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query) as Record<string, unknown>;
    const categoryId = optionalId(query['resourceCategoryId'], '자원 분류');
    const { page, size } = pagingOf(query);
    return transaction(async (db) => {
      // 미사용 자원은 목록에서 제외한다 (schema 주석: 미사용 자원은 신규 예약 제외)
      const conditions: string[] = ["use_status = '사용'"];
      const params: Record<string, unknown> = { limit: size, offset: page * size };
      if (categoryId !== null) {
        conditions.push('resource_category_id = CAST(:categoryId AS bigint)');
        params['categoryId'] = categoryId;
      }
      const where = conditions.join(' AND ');
      const countParams: Record<string, unknown> = {};
      if (categoryId !== null) {
        countParams['categoryId'] = categoryId;
      }
      const totalRows = await db.query(
        'SELECT COUNT(*) AS "total" FROM resource WHERE ' + where,
        countParams,
      );
      const items = await db.query(
        'SELECT resource_id AS "resourceId", name AS "name", ' +
          'resource_category_id AS "resourceCategoryId", ' +
          'visibility_scope AS "visibilityScope", ' +
          'approval_required AS "approvalRequired" ' +
          'FROM resource WHERE ' + where +
          ' ORDER BY sort_order NULLS LAST, resource_id LIMIT :limit OFFSET :offset',
        params,
      );
      return { items, page, size, total: Number(totalRows[0].total) };
    });
  }

  @Get('/resource-reservations')
  async listResourceReservations(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query) as Record<string, unknown>;
    const viewType = String(query['viewType'] ?? '');
    const baseDate = String(query['baseDate'] ?? '');
    const range = VIEW_RANGE[viewType];
    if (!range) {
      throw invalid('조회 형태는 일간, 주간, 월간 중 하나여야 합니다.');
    }
    if (!/^\d{4}-\d{2}-\d{2}$/.test(baseDate)) {
      throw invalid('조회 기준일을 YYYY-MM-DD 형식으로 입력하세요.');
    }
    const resourceId = optionalId(query['resourceId'], '자원');
    const categoryId = optionalId(query['resourceCategoryId'], '자원 분류');
    const { page, size } = pagingOf(query);
    return transaction(async (db) => {
      const conditions: string[] = [
        'r.start_at < ' + range.to,
        'r.end_at >= ' + range.from,
      ];
      const params: Record<string, unknown> = { baseDate };
      if (resourceId !== null) {
        conditions.push('r.resource_id = CAST(:resourceId AS bigint)');
        params['resourceId'] = resourceId;
      }
      if (categoryId !== null) {
        conditions.push('s.resource_category_id = CAST(:categoryId AS bigint)');
        params['categoryId'] = categoryId;
      }
      const where = conditions.join(' AND ');
      const from = 'FROM resource_reservation r JOIN resource s ON s.resource_id = r.resource_id WHERE ' + where;
      const totalRows = await db.query('SELECT COUNT(*) AS "total" ' + from, params);
      const items = await db.query(
        'SELECT r.resource_reservation_id AS "resourceReservationId", ' +
          'r.resource_id AS "resourceId", r.title AS "title", ' +
          'r.start_at AS "startAt", r.end_at AS "endAt", ' +
          'r.approval_status AS "approvalStatus" ' +
          from +
          ' ORDER BY r.start_at, r.resource_reservation_id LIMIT :limit OFFSET :offset',
        { ...params, limit: size, offset: page * size },
      );
      return { items, page, size, total: Number(totalRows[0].total) };
    });
  }

  @Get('/resource-reservations/:resourceReservationId')
  async getResourceReservation(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const id = req.params['resourceReservationId'];
    return transaction(async (db) => {
      if (!/^\d+$/.test(id)) {
        throw new ApiError(404, 'RESOURCE_RESERVATION_NOT_FOUND', '예약을 찾을 수 없거나 조회 권한이 없습니다.');
      }
      const rows = await db.query(
        'SELECT resource_reservation_id AS "resourceReservationId", ' +
          'resource_id AS "resourceId", reserver_id AS "reserverId", ' +
          'user_id AS "userId", title AS "title", start_at AS "startAt", ' +
          'end_at AS "endAt", repeat_rule AS "repeatRule", ' +
          'approval_status AS "approvalStatus" ' +
          'FROM resource_reservation WHERE resource_reservation_id = CAST(:id AS bigint)',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'RESOURCE_RESERVATION_NOT_FOUND', '예약을 찾을 수 없거나 조회 권한이 없습니다.');
      }
      return rows[0];
    });
  }
}

