import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Field,
  Select,
  DateInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const VIEW_TYPES: [string, string][] = [
  ['일간', '일간'],
  ['주간', '주간'],
  ['월간', '월간'],
];

function today(): string {
  return new Date().toISOString().slice(0, 10);
}

function emptyPage(): Page {
  return { items: [], page: 0, size: 20, total: 0 };
}

function ReservationDetail({ id, role, onClose }: { id: number; role: string; onClose: () => void }) {
  const { data, error, loading } = useData<Row>(
    () => call('GET', '/resource-reservations/' + id, role),
    [id],
  );
  return (
    <Drawer title='예약 내역 상세' onClose={onClose}>
      {loading && <p>불러오는 중입니다.</p>}
      {error && <ErrorText text={error} />}
      {data && (
        <Pairs
          items={[
            ['자원', <RefName table='resource' role={role} value={data.resourceId} />],
            ['예약 내용', String(data.title ?? '')],
            ['예약자', <RefName table='employee' role={role} value={data.reserverId} />],
            ['사용자', <RefName table='employee' role={role} value={data.userId} />],
            ['시작 일시', <DateText value={data.startAt} time />],
            ['종료 일시', <DateText value={data.endAt} time />],
            ['반복 설정', String(data.repeatRule ?? '-')],
            ['예약 승인 상태', <Badge value={data.approvalStatus} />],
          ]}
        />
      )}
    </Drawer>
  );
}

export default function FnSfr03301Page({ role }: PageProps) {
  const [viewType, setViewType] = useState('주간');
  const [baseDate, setBaseDate] = useState(today());
  const [resourceId, setResourceId] = useState<unknown>('');
  const [categoryId, setCategoryId] = useState<unknown>('');
  const [applied, setApplied] = useState({
    viewType: '주간',
    baseDate: today(),
    resourceId: '' as unknown,
    categoryId: '' as unknown,
  });
  const [page, setPage] = useState(0);
  const [resPage, setResPage] = useState(0);
  const [formError, setFormError] = useState('');
  const [selectedId, setSelectedId] = useState<number | null>(null);

  const reservations = useData<Page>(
    () => {
      if (!applied.baseDate) {
        return Promise.resolve(emptyPage());
      }
      return call<Page>('GET', '/resource-reservations', role, undefined, {
        viewType: applied.viewType,
        baseDate: applied.baseDate,
        resourceId: applied.resourceId,
        resourceCategoryId: applied.categoryId,
        page,
      });
    },
    [applied, page, role],
  );

  const resources = useData<Page>(
    () =>
      call<Page>('GET', '/resources', role, undefined, {
        resourceCategoryId: applied.categoryId,
        page: resPage,
        size: 10,
      }),
    [applied.categoryId, resPage, role],
  );

  const search = () => {
    if (!baseDate) {
      setFormError('조회 기준일을 입력하세요.');
      return;
    }
    setFormError('');
    setPage(0);
    setResPage(0);
    setApplied({ viewType, baseDate, resourceId, categoryId });
  };

  const reset = () => {
    setViewType('주간');
    setBaseDate(today());
    setResourceId('');
    setCategoryId('');
    setFormError('');
    setPage(0);
    setResPage(0);
    setApplied({ viewType: '주간', baseDate: today(), resourceId: '', categoryId: '' });
  };

  const resData = reservations.data;
  const resList = resources.data;

  return (
    <div className='bento'>
      <section className='box span-12'>
        <h2>예약 현황</h2>
        <Tiles
          items={[
            ['조회 기간 예약', <Num value={resData ? resData.total : 0} />],
            ['사용 가능 자원', <Num value={resList ? resList.total : 0} />],
          ]}
        />
      </section>

      <section className='box span-8'>
        <h2>자원 캘린더</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label='일간/주간/월간' required>
            <Select value={viewType} onChange={setViewType} options={VIEW_TYPES} placeholder='선택' />
          </Field>
          <Field label='조회 기준일' required>
            <DateInput value={baseDate} onChange={setBaseDate} />
          </Field>
          <Field label='자원 분류'>
            <LookupSelect
              table='resource_category'
              role={role}
              value={categoryId}
              onChange={setCategoryId}
              placeholder='전체'
            />
          </Field>
          <Field label='자원'>
            <LookupSelect
              table='resource'
              role={role}
              value={resourceId}
              onChange={setResourceId}
              placeholder='전체'
            />
          </Field>
        </Filters>
        {formError && <ErrorText text={formError} />}
        {reservations.error && <ErrorText text={reservations.error} />}
        <Band total={resData ? resData.total : 0} />
        <DataTable
          columns={[
            {
              key: 'resourceId',
              label: '자원',
              render: (row) => <RefName table='resource' role={role} value={row.resourceId} />,
            },
            { key: 'title', label: '예약 내용' },
            {
              key: 'startAt',
              label: '시작 일시',
              render: (row) => <DateText value={row.startAt} time />,
            },
            {
              key: 'endAt',
              label: '종료 일시',
              render: (row) => <DateText value={row.endAt} time />,
            },
            {
              key: 'approvalStatus',
              label: '예약 승인 상태',
              render: (row) => <Badge value={row.approvalStatus} />,
            },
          ]}
          rows={resData ? resData.items : []}
          onRowClick={(row) => setSelectedId(Number(row.resourceReservationId))}
          empty='조회 조건에 해당하는 예약이 없습니다.'
        />
        {resData && (
          <Pager page={resData.page} size={resData.size} total={resData.total} onPage={setPage} />
        )}
      </section>

      <section className='box span-4'>
        <h2>사용 가능 자원</h2>
        {resources.error && <ErrorText text={resources.error} />}
        <DataTable
          columns={[
            { key: 'name', label: '자원명' },
            {
              key: 'resourceCategoryId',
              label: '자원 분류',
              render: (row) => (
                <RefName table='resource_category' role={role} value={row.resourceCategoryId} />
              ),
            },
            { key: 'visibilityScope', label: '공개범위' },
            { key: 'approvalRequired', label: '승인 절차 사용 여부' },
          ]}
          rows={resList ? resList.items : []}
          onRowClick={(row) => {
            setResourceId(row.resourceId);
            setApplied({ viewType, baseDate, resourceId: row.resourceId, categoryId });
            setPage(0);
          }}
          empty='사용 가능한 자원이 없습니다.'
        />
        {resList && (
          <Pager page={resList.page} size={resList.size} total={resList.total} onPage={setResPage} />
        )}
      </section>

      {selectedId !== null && (
        <ReservationDetail id={selectedId} role={role} onClose={() => setSelectedId(null)} />
      )}
    </div>
  );
}
